function xySeriesRoute (value) {
  if (!value || typeof value !== 'object' ||
    typeof value.streamId !== 'string' || !value.streamId.trim() || value.streamId.length > 255 ||
    ![value.eventPath, value.manifestPath].every(path => typeof path === 'string' &&
      /^\/\/[^/]/.test(path) && path.length <= 1026) || value.eventPath === value.manifestPath) {
    throw Error('Invalid xy-series delivery metadata')
  }
  return { streamId: value.streamId, eventPath: value.eventPath, manifestPath: value.manifestPath }
}

module.exports = { xySeriesRoute }
